<?php
require_once __DIR__ . '/partials.php'; require_login();
$uid = user_id();
$s = db()->prepare("SELECT items.*, (SELECT COUNT(*) FROM requests WHERE item_id=items.id AND status='pending') AS pending_count FROM items WHERE owner_id=? ORDER BY created_at DESC");
$s->bind_param('i',$uid); $s->execute(); $mine=$s->get_result()->fetch_all(MYSQLI_ASSOC);
$s = db()->prepare('SELECT requests.*, items.title, items.owner_id, users.name AS borrower_name FROM requests JOIN items ON items.id=requests.item_id JOIN users ON users.id=requests.borrower_id WHERE items.owner_id=? ORDER BY requests.created_at DESC');
$s->bind_param('i',$uid); $s->execute(); $incoming=$s->get_result()->fetch_all(MYSQLI_ASSOC);
$s = db()->prepare('SELECT requests.*, items.title, users.name AS owner_name FROM requests JOIN items ON items.id=requests.item_id JOIN users ON users.id=items.owner_id WHERE requests.borrower_id=? ORDER BY requests.created_at DESC');
$s->bind_param('i',$uid); $s->execute(); $outgoing=$s->get_result()->fetch_all(MYSQLI_ASSOC);
page_header('My dashboard');
?>
<section class="page-intro"><p class="eyebrow">Your sharing space</p><h1>Hello, <?= e($_SESSION['user_name'] ?? 'student') ?>.</h1><p>Keep track of what you shared and what you borrowed.</p><a class="button" href="add.php">List another item →</a></section>
<section class="dashboard-section"><div class="section-heading"><h2>My items</h2><span class="count-pill"><?= count($mine) ?></span></div><?php if (!$mine): ?><p class="hint">You have not listed anything yet.</p><?php endif; ?><?php foreach ($mine as $item): ?><article class="list-row"><div><span class="tag"><?= e($item['category']) ?></span><h3><a href="item.php?id=<?= (int)$item['id'] ?>"><?= e($item['title']) ?></a></h3><p><?= e($item['pickup_location']) ?> · <?= e($item['status']) ?> · <?php if ($item['pricing_mode']==='hourly'): ?>₹<?= number_format((float)$item['hourly_rate'],2) ?>/hour<?php else: ?><?= (float)$item['borrowing_fee'] > 0 ? '₹'.number_format((float)$item['borrowing_fee'],2).' flat' : 'Free' ?><?php endif; ?> · <?= (int)$item['pending_count'] ?> pending</p></div><div class="row-actions"><?php if ($item['status'] === 'available'): ?><a class="subtle-button" href="edit.php?id=<?= (int)$item['id'] ?>">Edit</a><?php endif; ?><form action="action.php" method="post" onsubmit="return confirm('Remove this listing and its requests?')"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="item_id" value="<?= (int)$item['id'] ?>"><button class="subtle-button" name="action" value="delete_item">Remove</button></form></div></article><?php endforeach; ?></section>
<section class="dashboard-section"><div class="section-heading"><h2>Requests for my items</h2><span class="count-pill"><?= count($incoming) ?></span></div><?php if (!$incoming): ?><p class="hint">No requests yet.</p><?php endif; ?><?php foreach ($incoming as $request): ?><article class="list-row"><div><span class="status <?= e($request['status']) ?>"><?= e(ucfirst($request['status'])) ?></span><h3><?= e($request['title']) ?></h3><p>From <?= e($request['borrower_name']) ?> · “<?= e($request['message']) ?>”<?php if ($request['start_at']): ?> · Pickup <?= e(date('d M Y, g:i A',strtotime($request['start_at']))) ?> · Return <?= e(date('d M Y, g:i A',strtotime($request['end_at']))) ?><?php elseif ($request['due_date']): ?> · Return by <?= e($request['due_date']) ?><?php endif; ?></p><?php if ((float)$request['agreed_fee'] > 0): ?><p class="payment-note">Agreed fee: ₹<?= number_format((float)$request['agreed_fee'],2) ?><?php if ($request['pricing_mode']==='hourly'): ?> (₹<?= number_format((float)$request['agreed_rate'],2) ?> × <?= (int)$request['billable_hours'] ?> billed hours)<?php endif; ?> · <?= e(strtoupper($request['payment_method'])) ?> at pickup · <?= $request['paid_at'] ? 'Received' : 'Not yet marked received' ?></p><?php endif; ?></div><?php if ($request['status'] === 'pending'): ?><div class="row-actions"><form action="action.php" method="post"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="request_id" value="<?= (int)$request['id'] ?>"><?php if (!$request['end_at']): ?><label class="due-label" for="due-<?= (int)$request['id'] ?>">Return by</label><input class="due-input" id="due-<?= (int)$request['id'] ?>" type="date" name="due_date" min="<?= date('Y-m-d') ?>" max="<?= date('Y-m-d',strtotime('+1 year')) ?>" required><?php endif; ?><button class="small-button" name="action" value="approve">Approve</button></form><form action="action.php" method="post"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="request_id" value="<?= (int)$request['id'] ?>"><button class="subtle-button" name="action" value="decline">Decline</button></form></div><?php elseif ($request['status'] === 'approved'): ?><div class="row-actions"><?php if ((float)$request['agreed_fee'] > 0 && !$request['paid_at']): ?><form action="action.php" method="post"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="request_id" value="<?= (int)$request['id'] ?>"><button class="subtle-button" name="action" value="mark_paid">Mark payment received</button></form><?php endif; ?><form action="action.php" method="post"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="request_id" value="<?= (int)$request['id'] ?>"><button class="small-button" name="action" value="return">Mark returned</button></form></div><?php elseif ($request['status'] === 'returned' && (float)$request['agreed_fee'] > 0 && !$request['paid_at']): ?><form action="action.php" method="post"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="request_id" value="<?= (int)$request['id'] ?>"><button class="subtle-button" name="action" value="mark_paid">Mark payment received</button></form><?php endif; ?></article><?php endforeach; ?></section>
<section class="dashboard-section"><div class="section-heading"><h2>My borrowing requests</h2><span class="count-pill"><?= count($outgoing) ?></span></div><?php if (!$outgoing): ?><p class="hint">You have not requested an item yet.</p><?php endif; ?><?php foreach ($outgoing as $request): ?><article class="list-row"><div><span class="status <?= e($request['status']) ?>"><?= e(ucfirst($request['status'])) ?></span><h3><?= e($request['title']) ?></h3><p>Shared by <?= e($request['owner_name']) ?><?php if ($request['start_at']): ?> · Pickup <?= e(date('d M Y, g:i A',strtotime($request['start_at']))) ?> · Return <?= e(date('d M Y, g:i A',strtotime($request['end_at']))) ?><?php elseif ($request['due_date']): ?> · Return by <?= e($request['due_date']) ?><?php endif; ?></p><?php if ((float)$request['agreed_fee'] > 0): ?><p class="payment-note">Agreed fee: ₹<?= number_format((float)$request['agreed_fee'],2) ?><?php if ($request['pricing_mode']==='hourly'): ?> (₹<?= number_format((float)$request['agreed_rate'],2) ?> × <?= (int)$request['billable_hours'] ?> billed hours)<?php endif; ?> · <?= e(strtoupper($request['payment_method'])) ?> at pickup · <?= $request['paid_at'] ? 'Received' : 'Not yet marked received' ?></p><?php endif; ?></div><?php if ($request['status'] === 'pending'): ?><form action="action.php" method="post"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="request_id" value="<?= (int)$request['id'] ?>"><button class="subtle-button" name="action" value="cancel">Cancel</button></form><?php endif; ?></article><?php endforeach; ?></section>
<?php page_footer(); ?>
